import React, { useEffect, useState } from 'react';

function detail() {
    // const [data, setData] = useState([]);
    // useEffect(() => {
    //     fetchData();
    // }, []);

    // const fetchData = ()=>{
    //     fetch('http://192.168.0.67:8080/exam/detail',
    //         {
    //             method: 'GET',
    //             headers: {
    //                 'Accept': 'application/json'
    //             }
    //         }
    //     )
    //     .then(answer => answer.json())
    //     .then(data => setData(data))
    //     .catch(err=>console.log('error: '+err.message))
    // }

    return (
        <div>
            상세페이지
            <br/>
            {data.reg_date}
            <table border="">
                <tr>
                    <td>학기</td>		<td>{data.hakgi}</td>
                </tr><tr>
                    <td>시험</td>		<td>{data.name}</td>
                </tr><tr>
                    <td>학생ID</td>	    <td>{data.pid}</td>
                </tr><tr>
                    <td>시험일</td>	    <td>{data.regDate}</td>
                </tr><tr>
                    <td>국어</td>		<td>{data.kor}</td>
                </tr><tr>
                    <td>영어</td>		<td>{data.eng}</td>
                </tr><tr>
                    <td>수학</td>		<td>{data.mat}</td>
                </tr><tr>
                    <td>파일</td>		<td>{data.ff}</td>
                </tr>
            </table>
        </div>
    );
}

function ExamDetail(props) {

    const [data, setData] = useState([]);
    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = ()=>{
        fetch('http://192.168.0.67:8080/exam/detail',
            {
                method: 'GET',
                headers: {
                    'Accept': 'application/json'
                }
            }
        )
        .then(answer => answer.json())
        .then(data => setData(data))
        .catch(err=>console.log('error: '+err.message))
    }

    return (
        <div>
            상세페이지
            <br/>
            {data.reg_date}
            <table border="">
                <tr>
                    <td>학기</td>		<td>{data.hakgi}</td>
                </tr><tr>
                    <td>시험</td>		<td>{data.name}</td>
                </tr><tr>
                    <td>학생ID</td>	    <td>{data.pid}</td>
                </tr><tr>
                    <td>시험일</td>	    <td>{data.regDate}</td>
                </tr><tr>
                    <td>국어</td>		<td>{data.kor}</td>
                </tr><tr>
                    <td>영어</td>		<td>{data.eng}</td>
                </tr><tr>
                    <td>수학</td>		<td>{data.mat}</td>
                </tr><tr>
                    <td>파일</td>		<td>{data.ff}</td>
                </tr>
            </table>
            <BrowserRouter>
                <Routes>
                    <Route path='/detail' element={<detail />}/>
                </Routes>
            </BrowserRouter>
        </div>
    );
}

export default ExamDetail;
